box\": [{\"coord\": [100, 481, 756, 551], \"page_id\": 121}], \"content\": \"3 Weekly worldwide net positions of banks and banking institutions in the United States, and their foreign branches and majority-owned foreign subsidiaries. Excludes capital assets and liabilities.\", \"description\": null, \"id\": 6, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [100, 555, 516, 580], \"page_id\": 121}], \"content\": \"4 Foreign branches and majority-owned subsidiaries only.\", \"description\": null, \"id\": 7, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [100, 625, 389, 648], \"page_id\": 121}], \"content\": \"SECTIONS II THROUGH VII\", \"description\": null, \"id\": 8, \"type\": \"section_header\"}, {\"bbox\": [{\"coord\": [100, 666, 756, 738], \"page_id\": 121}], \"content\": \"Positions of nonbanking business concerns in the United States and their foreign branches and majority-owned partnerships and subsidiaries. In section VII positions of foreign branches and majority-owned partnerships and subsidiaries only.\", \"description\": null, \"id\": 9, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [794, 275, 1452, 348], \"page_id\": 121}], \"content\": \"2 Excludes receivables and installment paper sold or discounted before maturity, fixed assets (plant and equipment), and parents' investment in majority-owned foreign subsidiaries.\", \"description\": null, \"id\": 10, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [794, 354, 1193, 379], \"page_id\": 121}], \"content\": \"3. Capitalized plant and equipment leases are excluded.\", \"description\": null, \"id\": 11, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [794, 384, 1148, 408], \"page_id\": 121}], \"content\": \"4 Includes both spot and forward exchange rates.\", \"description\": null, \"id\": 12, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [795, 413, 1094, 438], \"page_id\": 121}], \"content\": \"5 Columns 1 and 3 less columns 2 and 4.\", \"description\": null, \"id\": 13, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [795, 445, 1452, 517], \"page_id\": 121}], \"content\": \"Representative rates on the report date. Canadian dollar and United Kingdom pound rates are expressed in U.S. dollars per unit of foreign currency, all others in foreign units per U.S. dollar. The source of the automated representative rates changed as of June 30, 1988.\", \"description\": null, \"id\": 14, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [794, 521, 1454, 587], \"page_id\": 121}], \"content\": \"Banks and banking institutions in the United States and their foreign branches and majority-owned subsidiaries. In section VII, foreign branches and majority-owned subsidiaries only.\", \"description\": null, \"id\": 15, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [794, 596, 986, 616], \"page_id\": 121}], \"content\": \"Excludes capital assets.\", \"description\": null, \"id\": 16, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [794, 623, 1000, 645], \"page_id\": 121}], \"content\": \"9 Excludes capital liabilities.\", \"description\": null, \"id\": 17, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [794, 652, 1191, 677], \"page_id\": 121}], \"content\": \"10 Includes both spot and forward exchange contracts.\", \"description\": null, \"id\": 18, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [794, 682, 1117, 706], \"page_id\": 121}], \"content\": \"11 Columns 3 and 9 less columns 6 and 12.\", \"description\": null, \"id\": 19, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [794, 713, 932, 738], \"page_id\": 121}], \"content\": \"12 See footnote 6.\", \"description\": null, \"id\": 20, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [64, 54, 107, 76], \"page_id\": 122}], \"content\": \"108\", \"description\": null, \"id\": 0, \"type\": \"page_number\"}, {\"bbox\": [{\"coord\": [517, 119, 960, 142], \"page_id\": 122}], \"content\": \"EXCHANGE STABILIZATION FUND\", \"description\": null, \"id\": 1, \"type\": \"section_header\"}, {\"bbox\": [{\"coord\": [645, 189, 835, 209], \"page_id\": 122}], \"content\": \"INTRODUCTION\", \"description\": null, \"id\": 2, \"type\": \"section_header\"}, {\"bbox\": [{\"coord\": [64, 252, 173, 272], \"page_id\": 122}], \"content\": \"Background\", \"description\": null, \"id\": 3, \"type\": \"section_header\"}, {\"bbox\": [{\"coord\": [61, 299, 712, 484], \"page_id\": 122}], \"content\": \"The Exchange Stabilization Fund (ESF) was established under the Gold Reserve Act of January 30, 1934 (31 U.S.C. 822a). This act authorized the establishment in the Department of the Treasury of a stabilization fund to be operated under the exclusive control of the Secretary of the Treasury, with the approval of the President, for the purpose of stabilizing the exchange value of the dollar. Subsequent amendment of the Gold Reserve Act modified the original purpose somewhat to reflect termination of the fixed exchange rate system.\", \"description\": null, \"id\": 4, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [64, 513, 712, 583], \"page_id\": 122}], \"content\": \"The resources of the fund consist of dollar balances, partly invested in U.S. Government securities, special drawing rights (SDRs), and balances of foreign currencies.\", \"description\": null, \"id\": 5, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [63, 610, 716, 675], \"page_id\": 122}], \"content\": \"The principal sources of income or losses for the ESF have been profits or losses on holdings of and transactions in SDRs and foreign exchange, and the interest earned on assets.\", \"description\": null, \"id\": 6, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [63, 731, 161, 745], \"page_id\": 122}], \"content\": \"Definitions\", \"description\": null, \"id\": 7, \"type\": \"section_header\"}, {\"bbox\": [{\"coord\": [61, 778, 712, 866], \"page_id\": 122}], \"content\": \"Special drawing rights--International assets created by the International Monetary Fund (IMF). They serve to increase international liquidity and provide additional international reserves, and may be purchased and sold among eligible holders through the IMF.\", \"description\": null, \"id\": 8, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [61, 893, 712, 938], \"page_id\": 122}], \"content\": \"SDR allocations.--The counterpart of SDRs issued by the IMF based on members' quota in the IMF. Although shown in ESF state-\", \"description\": null, \"id\": 9, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [762, 252, 1413, 317], \"page_id\": 122}], \"content\": \"ments as liabilities, they must be redeemed by the ESF only in the event of liquidation of, or U.S. withdrawal from, the SDR Department of the IMF or cancellation of SDRs.\", \"description\": null, \"id\": 10, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [762, 344, 1413, 432], \"page_id\": 122}], \"content\": \"SDR certificates--Issued to the Federal Reserve System against SDRs when SDRs are \\\"monetized\\\" and the proceeds of the monetization are deposited in an ESF account at the Federal Reserve Bank of New York.\", \"description\": null, \"id\": 11, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [762, 488, 960, 506], \"page_id\": 122}], \"content\": \"Description of Tables\", \"description\": null, \"id\": 12, \"type\": \"section_header\"}, {\"bbox\": [{\"coord\": [763, 536, 1413, 720], \"page_id\": 122}], \"content\": \"Table ESF-1 presents the assets, liabilities, and capital of the ESF. Data are presented in U.S. dollars or U.S. dollar equivalents based on current exchange rates computed according to the accrual method of accounting. The capital account represents the original capital appropriated to the ESF by Congress of $2 billion, less a subsequent transfer of $1.8 billion to pay for the initial U.S. quota subscription to the IMF. Subsequent gains and losses since inception are reflected in the cumulative net income (loss) account.\", \"description\": null, \"id\": 13, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [763, 749, 1413, 938], \"page_id\": 122}], \"content\": \"Table ESF-2 presents the results of operations by quarter. Data are presented in U.S. dollars or U.S. dollar equivalents computed according to the accrual method of accounting. The \\\"Profit (loss) on foreign exchange\\\" includes realized profits (losses) on sales of foreign currencies as well as revaluation gains (losses) on currencies held. \\\"Adjustment for change in valuation of SDR holdings and allocations\\\" reflects the net gain (loss) on revaluation of SDR holdings and allocations for the quarter.\", \"description\": null, \"id\": 14, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [1395, 54, 1442, 81], \"page_id\": 123}], \"content\": \"109\", \"description\": null, \"id\": 0, \"type\": \"page_number\"}, {\"bbox\": [{\"coord\": [544, 104, 989, 135], \"page_id\": 123}], \"content\": \"EXCHANGE STABILIZATION FUND\", \"description\": null, \"id\": 1, \"type\": \"page_header\"}, {\"bbox\": [{\"coord\": [371, 153, 1165, 192], \"page_id\": 123}], \"content\": \"Table ESF-1.--Balances as of Dec. 31, 1989, and Mar. 31, 1990\", \"description\": null, \"id\": 2, \"type\": \"title\"}, {\"bbox\": [{\"coord\": [682, 199, 856, 221], \"page_id\": 123}], \"content\": \"(In thousands of dollars)\", \"description\": null, \"id\": 3, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [80, 219, 1447, 1205], \"page_id\": 123}], \"content\": \"<table><tr><th>Assets, liabilities, and capital</th><th>Dec. 31, 1989</th><th>Dec. 31, 1989, through Mar. 31, 1990</th><th>Mar. 31, 1990</th></tr><tr><td colspan=\\\"4\\\">Assets</td></tr><tr><td>U.S. dollars:</td><td></td><td></td><td></td></tr><tr><td>Held at Federal Reserve Bank of New York</td><td>454,336</td><td>460,222</td><td>914,558</td></tr><tr><td>Held with Treasury:</td><td></td><td></td><td></td></tr><tr><td>U.S. Government securities</td><td>405,711</td><td>(401,765)</td><td>3,946</td></tr><tr><td>Other</td><td>1,067,000</td><td>0</td><td>1,067,000</td></tr><tr><td>Special drawing rights 1</td><td>9,950,788</td><td>141,211</td><td>10,091,999</td></tr><tr><td>Foreign exchange and securities 2:</td><td