     in_segment = False\n    if in_segment:\n        segments.append((start, width))\n    return segments\n\n# Let's scan at various rows to understand the structure\nprint(\"Scanning rows around Exhibit 1 (around row 400):\")\nfor row in [350, 400, 450, 500]:\n    segments = find_line_segments(row)\n    if segments:\n        print(f\"Row {row}: {len(segments)} segments, total length: {sum(e-s for s,e in segments)}\")\n\nprint(\"\\nScanning rows around Exhibit 2 (around row 950):\")\nfor row in [900, 950, 1000, 1050]:\n    segments = find_line_segments(row)\n    if segments:\n        print(f\"Row {row}: {len(segments)} segments, total length: {sum(e-s for s,e in segments)}\")\n        \n# Also check the bottom plot (if any)\nprint(\"\\nScanning rows around Exhibit 2 bottom (around row 1150):\")\nfor row in [1100, 1150, 1200]:\n    segments = find_line_segments(row)\n    if segments:\n        print(f\"Row {row}: {len(segments)} segments, total length: {sum(e-s for s,e in segments)}\")\nEOF"}}},"_meta":{"goose_extension":"developer"}}],"metadata":{"userVisible":true,"agentVisible":true}}}
